insert into public.publishers (exhibitor_no, booth_number, original_booth_number, name, name_en, country_ko, country_en, is_special, categories, introduction, homepage, instagram, sort_order) values
  (74, 'A1401', null, '이룸아이', 'ErumI Publishing Co.', null, null, false, array['아동']::text[], '어린이의 꿈과 희망이 뜻한 대로 이루어진다는 의미를 담은 이룸아이는 세계로 뻗어 나가는 어린이 도서 전문 출판사입니다. 어린이 도서 전 분야에서 감성과 지성을 고루 발달시키는 책을 만들어 가며, 아이들이 꿈꾸는 세상을 이룸아이에서 열어 갑니다. 미래를 이끌어 갈 어린이에게 꿈과 희망을 심어 주고, 그 꿈이 쑥쑥 자라도록 든든한 토대가 되는 책을 만들기 위해 노력합니다.이룸아이는 어린이 문화의 연결고리로서, 아이들이 꿈꾸고 상상할 수 있는 책을 만듭니다. 어린이의 꿈과 희망을 소중히 여기며, 빠른 길보다 바른 길을 선택합니다.', 'http://www.eribook.com', null, 74),
  (75, 'A1402', null, '펜타클', 'pentacle', null, null, false, array['사회과학','문학','역사']::text[], '펜타클출판사는 글의 힘으로 세상과 소통하며, 감동과 교양을 함께 전하는 출판사입니다. 청소년, 문학, 역사 등 다양한 분야의 도서를 출간하며, 독자에게 읽는 즐거움과 생각할 거리를 전하고자 합니다. 뉴스툰 시리즈와 고전툰 시리즈 등 복잡하거나 어렵게 느껴질 수 있는 주제를 보다 친근한 방식으로 풀어내는 청소년 교양서를 꾸준히 선보이고 있습니다. 앞으로도 글과 이야기가 지닌 가능성을 바탕으로, 독자와 함께 호흡하며 오래 곁에 남는 책을 만들어가고자 합니다.', null, 'https://www.instagram.com/pentaclebooks/', 75),
  (76, 'A1403', null, '마음모자', 'Maummoja', null, null, false, array['아동']::text[], '매일 하던 새벽 드로잉이 엄마의 마음을 거쳐 그림책이 되었습니다. 마음모자는 엄마와 아이의 관계에서 영감을 얻어 서로 돌보는 마음을 그림책에 담고 있습니다. 돌보는 마음은 아이들의 마음속에서 작은 그늘이 되어 자신을 보호할 것입니다. 어린 시절 이마에 닿았던 엄마의 다정한 손 그늘처럼 말입니다. 마음모자의 이야기가 오래도록 기억되도록 우리는 그림책의 경계를 넘어 접근성 전자책과 영상으로 확장해 나아가고 있습니다. 마음주머니 워크숍을 통해 삶을 그림책 예술로 도닥이며 독자들과 함께 합니다. 2024년 접근성 전자책 너의 이야기로 제11회 대한민국 전자출판 우수상을, 2025년 그림책 환호로 제3회 대한민국 그림책상 특별상을 수상하였습니다.', 'http://maummoja.com', null, 76),
  (77, 'A1404', null, '스토리보울', 'STORYBOWL', null, null, false, array['아동']::text[], '"삶을 더욱 달콤하게 하는 건, 언제나 이야기였다." - 백희나 스토리보울은 백희나 작가가 간직해 온 이야기를 하나씩 꺼내어 놓습니다. 재미나고 설레는 이야기가 되기를 바라며, 손으로 빚은 인형과 직접 촬영한 장면, 따뜻한 드로잉으로 어린이와 어른 모두에게 일상 속 마법 같은 순간을 전합니다. 이야기는 그림책을 넘어 전시와 영상, 공연, 굿즈 등으로 다채롭게 펼쳐집니다. 당신만의 이야기 그릇에, 백희나의 마법 같은 이야기 한 조각을 담아 보세요.', 'http://www.storybowl.com', 'https://www.instagram.com/storybowl_book/', 77),
  (78, 'A1405', null, '몽당연필', 'mongdangpencil', null, null, false, array['종교']::text[], '몽당연필은 하나님의 말씀을 어린이의 눈높이에 맞추어 전하는 데 헌신해 온 기독교 어린이 도서 전문 출판사입니다. 작은 연필이 끝까지 쓰임받듯, 한 아이 한 아이가 하나님의 귀한 도구로 쓰임받기를 소망하는 마음으로 책을 펴내고 있습니다.', null, 'https://www.instagram.com/vision_books_/', 78),
  (79, 'A1405', null, '구름이머무는동안', 'Cloud Stays Books', null, null, false, array['종교']::text[], '구름이머무는동안 출판사는 인생의 멈춤과 기다림의 시간동안 성장하고 회복할 수 있는 에세이를 출간하고 있는 기독교출판사입니다. 특히 습관, 감정, 결혼 등 삶에 밀접한 주제에 대한 책을 출간하고 있습니다.', null, 'https://www.instagram.com/cloudstays_books/', 79),
  (80, 'A1405', null, '뜰힘', 'DDEULHIM', null, null, false, array['종교']::text[], '뜰힘 출판사는 크지 않은 규모로 운영되지만, 그만큼 한 권 한 권에 집중하며 책을 만듭니다. 뜰힘은 신앙과 삶을 다루는 책을 중심으로, 익숙한 내용을 반복하기보다 새로운 관점과 해석을 담은 원고를 선택합니다. 성서를 다시 읽고, 공동체와 신앙을 오늘의 언어로 풀어내는 작업에 관심을 두고 있습니다. 많은 책을 빠르게 내기보다, 충분히 검토하고 다듬은 책을 꾸준히 출간하는 것을 중요하게 생각합니다. 독자가 오래 곁에 둘 수 있는 책, 다시 펼쳐 볼 수 있는 책을 만드는 것이 우리의 목표입니다. 뜨는 이야기보다 필요한 이야기를 선택하는 것, 그것이 뜰힘이 책을 만드는 방식입니다.', null, 'https://www.instagram.com/ddeulhim/', 80),
  (81, 'A1405', null, '소유', 'SOYOU BOOKS', null, null, false, array['종교']::text[], '소유는 책과 사람, 그리고 믿음을 연결하는 출판사입니다. 기독교 신앙을 기반으로, 그리스도인에게는 신앙의 깊이를 더하고, 비그리스도인에게는 믿음의 의미를 자연스럽게 경험할 수 있는 콘텐츠를 만듭니다. 우리는 말씀에서 출발한 이야기를 오늘의 언어로 재해석하여, 보이는 세계를 넘어서는 진리를 삶의 자리까지 전달합니다. 한 권의 책이 독자의 내면을 비추고, 삶을 다시 바라보게 하는 계기가 되기를 기대합니다.', 'http://www.soyoubooks.kr', 'https://www.instagram.com/soyoubooks/', 81),
  (82, 'A1405', null, '아르카', 'ARCA', null, null, false, array['종교']::text[], '일터행전, 절대1시간기도 등 기독인 대중의 일상생활에 도움이 되는 책 60여종을 펴낸 기독 도서 전문 출판사입니다.', 'http://blog.naver.com/arca_pub', null, 82),
  (83, 'A1405', null, '지우', 'Jiwoo Publisher', null, null, false, array['종교']::text[], '지우(知愚)는 ''자신의 어리석음을 알다''는 뜻입니다. 기독교는 자신의 어리석음을 깨닫고 그 한계를 인정하는 겸손한 종교이며, 그 겸손함으로 복음의 진리를 따릅니다. 지우는 바로 그 태도로 기독교의 진리를 하나하나 배워가고자 세운 출판사입니다. 기독교는 오랜 역사 속에서 다양한 해석의 갈래(교파)를 품어왔습니다. 지우는 그 넓은 지평을 두루 탐색하며, 신학과 신앙을 아우르고 다양한 해석 진영을 넘나드는 책을 만들고 있습니다. 깊은 신앙 경험이나 신학적 지식이 없어도, 누구나 손에 들고 읽을 수 있는 책, 그러나 결코 가볍지 않은 책을 지향합니다. 진리의 풍성함을 전하고 나와 생각이 달랐던 이들과 소통과 연대를 모색하는 것, 그것이 지우가 꿈꾸는 출판입니다. 앞으로 많은 관심과 응원 부탁드립니다', null, 'https://www.instagram.com/jiwoopub/', 83),
  (84, 'A1406', null, '(사)한국기독교출판협회', 'KCPA', null, null, false, array['기타(매거진)']::text[], '본 협회는 1975년 창립된 비영리 사단법인으로, 한국 기독교 출판 문화를 선도해 온 단체이며 120여 개 회원 출판사가 참여하고 있습니다. 월간 〈Christian Books & Life〉를 발행하고 다양한 출판 지원 사업을 통해 신앙과 출판을 연결하며, 기독교 출판 산업의 기반을 다져 왔습니다. 또한 신학, 목회, 신앙 일반 등 다양한 분야의 콘텐츠를 발굴·보급하고, 회원 출판사의 역량 강화를 위한 협력과 지원을 지속적으로 이어오고 있습니다. 아울러 국내외 도서전에 참가하여 한국 기독교 출판물을 널리 소개하고, 해외 출판계와의 교류를 확대함으로써 한국 기독교 출판의 위상을 높이고 있습니다.', 'http://kcpa.or.kr/', null, 84),
  (85, 'A1406', null, '도서출판 CUP', 'CUP (Christian University Press)', null, null, false, array['철학','종교','아동']::text[], 'CUP는 전인적인 삶의 틀을 제공하며, 성경적 비전을 확장시키는 그릇이 되고자 합니다. 기독교의 모든 가르침은 “우리는 무엇을 믿을 것인가?” 하는 물음과 “우리는 어떻게 살 것인가?” 하는 물음에 대한 답변이라 할 수 있습니다. 기독교가 바로 서려면, 바른 신학과 성경적 삶이라는 양 날개에 균형을 가져야 합니다. 믿는 것과 아는 것이 행함으로 연결되고, 신학과 가치관이 삶으로 이어져야 건강한 기독교가 세워집니다. CUP는 삶의 각 영역에서 어떻게 바른 가치관을 반영하고 살아낼 수 있는지 고민하고 나누며 비전을 확장시키는 소통의 장이 되기를 꿈꿉니다.', 'http://www.cupbooks.com', null, 85),
  (86, 'A1406', null, '도서출판 동연', 'DongYeon press', null, null, false, array['철학','종교','사회과학']::text[], '1992년 설립된 도서출판 동연은 지난 30여 년간 종교와 신학, 그리고 인문학을 잇는 학술서와 교양서를 출간해 왔습니다. 우리는 근원적 진리를 향한 신학적 성찰을 추구하며, 시대적 과제를 직시하는 날카로운 시선과 인간 내면을 어루만지는 따뜻한 통찰 사이의 균형을 지향합니다. 동연의 도서 목록은 『나그함마디 문서』와 같은 경전에서부터 헤겔, 카우츠키, 틸리히, 본회퍼 등 거장들의 저작, 그리고 『프란치스코 교황 어록』과 같은 대중적인 도서에 이르기까지 폭넓게 아우릅니다. 또한 『내면작업』과 『She』 같은 심리학 저작을 통해 자기 탐색의 길을 제시하는 한편, 『왜 세계는 팔레스타인 제노사이드에 침묵하는가?』와 『광장의 문화정치』 등의 필독서를 통해 현대 사회의 도전적 과제들에 응답하고 있습니다. 신학적 성찰과 인문학적 사유가 만나는 접점에서, 동연은 우리 사회를 풍요롭게 만드는 ‘한 권의 책이 가진 힘’에 정성을 다하고 있습니다.', null, 'https://www.instagram.com/dongyeon_press/', 86),
  (87, 'A1406', null, '문광서원', 'Mungwangbooks', null, null, false, array['종교']::text[], '"말씀으로 하나님의 빛을 전하는" 출판사 문광서원 문광서원은 복음의 불모지였던 조선을 위해 문광서원을 세우고 최초로 한글 성경을 번역하여 보급했던 존 로스 선교사의 귀한 뜻과 정신을 이어받아 오늘날 복음이 제한된 곳에 말씀을 보급하고 전하는 사명을 감당하고 있습니다. 이에 문서사역, 북한선교도서, 다음세대를 위한 문광KIDS 콘텐츠로 도서를 출간하고 있습니다.', 'https://www.munkwang.com', null, 87),
  (88, 'A1406', null, '바이블네비게이션(주)', 'Biblenavigation Inc.', null, null, false, array['종교','문학']::text[], '“어려웠던 성경, 이제 한눈에 이해하실 수 있습니다” 성경을 더 쉽고, 더 빠르게, 더 깊이 이해하도록 돕는 혁신적 콘텐츠를 개발하는 출판사입니다. 성경 66권과 1,189장을 구조적으로 정리한 성경과 성경, 그리고 말씀을 스토리로 풀어낸 신앙소설을 통해 독자들이 성경 전체의 흐름과 본질을 자연스럽게 연결하도록 합니다. 또한 성경 게임 앱과 영어판 콘텐츠로 확장하여, 언제 어디서나 반복 학습이 가능한 새로운 성경 교육 방식을 제시합니다. 말씀을 지식이 아닌 경험으로 전환시키는 콘텐츠로, 다음 세대까지 이어지는 성경 읽기의 새로운 기준을 만들어갑니다.', 'http://www.biblenavigation.com', null, 88),
  (89, 'A1406', null, '블리스', 'BLISS', null, null, false, array['종교']::text[], '책과 신앙을 잇는 섬김, 북서번트', null, 'https://www.instagram.com/bookservant__/', 89),
  (90, 'A1406', null, '쿰란출판사', 'Qumran Publishing House', null, null, false, array['종교','예술','역사']::text[], '쿰란출판사는, 1988년 하나님의 사랑과 복음을 전하는 목적으로 문서 선교의 사명을 가지고 출판을 시작해, 38년간 목회자 전문 서적, 성경 공부 교재, 평신도를 깨우는 신앙 서적들로 독자들을 만나왔습니다. 문화관광부 선정 우수학술도서와 청소년도서, 한국기독교출판문화상 최우수상 수상 등의 전문적 우수 도서를 통해 한국 교계에 좋은 영향력을 끼치고 있으며, 지금까지 출간된 4,000여 종의 도서들로 지속적으로 목회자와 성도들의 삶에 유익을 주는 출판사로 자리매김하고 있습니다.', 'http://www.qumran.co.kr/', 'https://instagram.com/qrbooks/', 90),
  (91, 'A1406', null, '템북', 'TEMBOOK', null, null, false, array['종교','문학','아동']::text[], '독자들이 배움의 즐거움을 발견하고 삶의 따뜻한 위로를 얻을 수 있도록, 단행본부터 전문 교재 및 교구까지 다채로운 콘텐츠를 정성껏 선보이는 출판사입니다. 주요 출간 분야로는 기초 학력 향상을 돕는 음운 인식 기반의 한글·영어 학습 프로그램이 있으며, 아이들의 언어 감각과 관계를 이어주는 동시집과 그림책도 꾸준히 펴내고있습니다. 또한 성경적 통찰을 담은 기독교 서적이나 신앙의 본질을 다룬 그래픽 노블 등 기독교적 가치를 현대적인 감각으로 풀어낸 양질의 도서들을 소개합니다. 템북은 교육 소외 계층을 배려한 체계적인 학습 콘텐츠와 전 세대가 공감할 수 있는 인문·종교 서적을 통해, 단순한 지식 전달을 넘어 사람의 마음을 움직이고 변화시키는 따뜻한 지혜를 나누고자 노력하고 있습니다.', 'http://tembook.kr', null, 91),
  (92, 'A1407', null, '아작', 'ARZAK', null, null, false, array['문학']::text[], '아작 출판사는 대한민국의 대표적인 SF 전문 출판사입니다. 하드 SF, 소프트 SF, 페미니즘 SF 등 다양한 SF 장르를 가리지 않고 출판해 SF의 다양성 확장에 애쓰고 있습니다. 주요 출간작으로는 문목하의 돌이킬 수 있는, 김보영의 다섯 번째 감각 등 한국 SF 소설을 비롯하여 코니 윌리스, 로버트 A. 하인라인, 아서 C. 클라크 등 해외 SF 거장들의 대표작들이 있습니다. 매니아층의 두터운 지지를 바탕으로 국내 장르 문학 시장을 이끌어가고 있습니다.', 'http://arzak.co.kr', null, 92),
  (93, 'A1408', null, '(주)이퍼블릭 코리아', 'tiramisu the book, safari', null, null, false, array['문학','아동']::text[], '티라미수 더북: 티라미수는 끌어 일으키다(tirare) + 나(mi) + 위(su)가 합쳐진 이탈리아어로, 티라미수 더북은 위로와 지혜, 활력을 전하는 인문 에세이 도서를 만듭니다. 사파리: 책 속으로 떠나는 즐거운 탐험, 사파리 유아 아동 청소년 도서를 만듭니다.', 'http://www.epublic.co.kr/business/list.asp#list', null, 93),
  (94, 'A1409', null, '도서출판 키다리', 'Kidari Publishing Co.', null, null, false, array['아동']::text[], '도서출판 키다리는 어린이와 어른이 함께 행복해지는 세상을 꿈꾸며 2004년에 문을 열었습니다. 유아어린이 픽션논픽션 그림책, 동화청소년책, 성인 단행본까지 다양한 책들을 출간했으며, 매년 수십 종의 다양한 도서를 꾸준히 발간하고 있습니다. 2017년부터 창작 그림책 브랜드 모래알을 통해 개성 있는 그림책들을 출간했으며, 2023년부터는 새로운 그림책 브랜드 다그림책을 통해 다 함께 즐기는 다양한 국내외 창작 그림책을 선보이고 있습니다.', 'https://www.kidaribook.kr/', 'https://www.instagram.com/kidaribook/', 94),
  (95, 'A1410', null, '에디토리얼', 'Editorial Publishing Co.', null, null, false, array['철학','사회과학','순수과학']::text[], '에디토리얼 출판사는 1994년부터 책을 만들어 온 편집자가 설립한 출판사입니다. 과학과 인문을 주력 분야로 하여 2018년 첫 책을 출간했으며, 과학과 인문학의 통합을 시도하는 책들이 독자와 오피니언 리더 들로부터 좋은 반응을 얻고 있습니다. 과학기술이 인간 및 사회와 맺는 관계에 관심을 갖고 그에 관한 다양한 주제들을 책에 담아내고자 노력하고 있습니다. 책을 읽는 행위가 세계와 연결된 사려 깊은 존재를 만들 수 있다는 가치를 실현하는 출판을 지향합니다.', 'https://www.editorialbooks.com/', null, 95),
  (96, 'A1410', null, '가지출판사', 'Kindsbook Publishing Company', null, null, false, array['기타(생태','문화','에세이)']::text[], '가지출판사는 생태, 문화, 에세이 분야 도서를 주로 펴내는 1인 출판사입니다. 인간 외 생명 존재들과의 상생, 차별 없는 더불어 삶을 추구하며 우리 일상을 좀 더 윤리적으로 바꿔줄 지식과 생각을 책에 담습니다.', null, 'https://www.instagram.com/kindsbook/', 96),
  (97, 'A1410', null, '메멘토', 'Memento Publishing Co.', null, null, false, array['철학','사회과학','역사']::text[], '메멘토는 2012년, 철학·역사·고전·사회과학 분야에서 활동해온 베테랑 편집자가 설립했다. 인문사회 연구자들과 협업해 완성도 높은 콘텐츠를 선보이며, 지난 14년간 꾸준히 양서를 출간해왔다. 전문서와 대중서 사이의 간극을 잇는 책을 지향하며, 새로운 시각과 글쓰기로 지적 자극을 주는 국내외 저자들과 함께 오래 기억될 책을 만들어가는 작지만 탄탄한 출판사다.', 'https://mementopub.tistory.com/', null, 97),
  (98, 'A1410', null, '목수책방', 'Moksu Publishing Company', null, null, false, array['순수과학','기타(정원','생태)']::text[], '목수책방의 주요 관심사는 인간과 자연의 공생, 그리고 지속가능한 삶입니다. 앞으로 계속해서 자연, 환경, 유기농업, 정원에 관한 좋은 책, 필요한 책을 만들어 많은 독자에게 소개하는 일을 하고자 합니다.', 'http://blog.naver.com/moksubooks', null, 98),
  (99, 'A1410', null, '혜화1117', 'Hyehwa1117 Publishing Company', null, null, false, array['예술','기타(인문교양)']::text[], '책 중심 문화공간 혜화1117. 2018년 첫 책을 낸 1인 출판사. 주로 인문교양, 문화예술 분야의 책을 만든다. 출판사의 이름은 서울 혜화동 작은 한옥의 도로명 주소에서 따온 것이다. 1994년부터 책을 만들어온 편집자가 책을 매개로 이어진 인연의 결과로 만든 공간에서 책을 기획하고 편집하는 것은 물론 완성된 책이 독자와 만나는 과정까지를 온전히 챙기고 즐기며 일상과 노동을 함께 하고 있다.', null, 'https://www.instagram.com/hyehwa1117/', 99),
  (100, 'A1501', null, '시공사', 'SIGONGSA', null, null, false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], 'SIGONGSA는 시간과 공간을 넘어 사람과 이야기를 연결하는 콘텐츠 기업으로, 변화하는 환경 속에서 새로운 방식의 독서와 콘텐츠 경험을 만들어 가고 있습니다. 30여 년간 책을 통해 읽기의 즐거움을 전해온 출판사로서, 창의열정조화라는 핵심 가치를 실천하며 독자와 함께 미래의 콘텐츠 환경을 확장해 나가고 있습니다. SIGONGSA는 디지털 콘텐츠와 IP 확장, 오프라인 경험까지 아우르며, 도서전과 같은 문화의 현장에서 새로운 이야기와 만남의 가능성을 제시하고자 합니다.', 'https://www.sigongsa.com', null, 100),
  (101, 'A1502', null, '전국동네책방네트워크', 'Korea Local bookshop network', null, null, false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], '전국동네책방네트워크: 우리 동네 독서생태계를 살리는 건강한 실핏줄 전국동네책방네트워크는 전국 곳곳에 뿌리 내린 동네책방들이 연대하여 건강한 독서 문화를 일구는 비영리 단체입니다. 우리는 지역 곳곳에서 독자와 책을 잇는 ‘문화 실핏줄’로서 로컬 독서생태계 자생력을 높이고, 지속 가능한 새로운 출판 생태계 바탕을 마련하려 애쓰고 있습니다. 특히 책방지기들의 고유한 안목과 철학이 담긴 ''큐레이션''은 우리 활동의 핵심입니다. 개성 있는 큐레이션을 중심으로 펼쳐지는 다채로운 북페어 기획과 진행를 통해, 대형 유통망이 담아내지 못하는 책의 가치를 발견하고 독자와 깊게 호흡합니다. 책을 매개로 지역과 사람을 연결하는 전국동네책방네트워크는 오늘도 우리 곁문화 사랑방 공간으로 책의 기쁨을 나누고 있습니다.', null, 'https://www.instagram.com/chaegbangnet/', 101),
  (102, 'A1503', null, '엘르 코리아', 'ELLE Korea', null, null, false, '{}'::text[], null, null, null, 102),
  (103, 'A1601', null, '(주)열린책들', 'The Open Books Co.', null, null, false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], '은 독자의 손에서 물리적으로 펼쳐져 읽히는 책이라는 의미와 함께, 경계를 넘어서는 창조적이고 개방적인 사고가 담긴 책이라는 뜻을 담고 있습니다.', 'http://www.openbooks.co.kr', null, 103),
  (104, 'A1602', null, '(주)오팬하우스', 'OFANHOUSE', null, null, false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], '오팬하우스는 소설, 라이트노벨, 코믹, 일반서 등 다양한 해외 출판물을 적극 번역 출판하고, 한국 오리지널 콘텐츠 기획출판에도 주력하는 IP 하우스입니다. 로맨틱 소설 , 장르소설 , 감성 에세이 , 라이트노벨코믹 , 자기계발 , 만화코믹에세이 , 스릴러 등 브랜드를 통해 독창적 콘텐츠를 선보이며, 원작 IP 기반 MD이벤트영상화 등 미디어믹스 사업으로 새로운 팬덤 문화를 만들어가고자 합니다.', 'https://www.ofanhouse.com/', 'https://www.instagram.com/ofanhouse.official/', 104),
  (105, 'A1701', null, '교보문고', 'KYOBO BOOK CENTRE', null, null, false, array['사회과학','문학','전자출판']::text[], '교보문고는 1980년 서울 종로 1번지에서 시작한 대한민국 대표 서점입니다. 국내 최대 수준의 장서를 보유하고, 전국 34개 오프라인 매장과 온라인 서점을 함께 운영하고 있습니다. 북클럽 회원 1,800만 명을 기반으로 책을 중심으로 한 지식문화 경험을 확장하며, 세대를 아우르는 신뢰 받는 지식문화 플랫폼으로 자리하고 있습니다.', 'https://www.kyobobook.co.kr/', 'https://www.instagram.com/kyobobook_online/', 105),
  (106, 'A1701', null, '교보생명 서재', 'Kyobo Life', null, null, false, array['기타']::text[], '교보생명은 지식과 문화의 힘으로 사람의 마음을 잇는 길을 걸어왔습니다. 교보문고와 광화문글판, 대산문화재단의 뿌리가 된 ''책과 사람''의 가치는 이제 독서 커뮤니티 플랫폼인 ''서재'' 서비스로 이어집니다. 혼자 읽는 즐거움을 넘어, 함께 나누는 독서의 가치를 교보로부터 경험해 보세요.', 'https://www.kyobo.com/', null, 106),
  (107, 'A1702', null, '주식회사 케이티밀리의서재', 'kt millie seojae Co.,Ltd', null, null, false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], '독서와 무제한 친해지리라는 마음으로 2016년 시작한 밀리의서재는, 2017년 국내 최초 전자책 구독 서비스를 통해 우리 삶에 독서가 스며들 수 있도록 힘쓰고 있습니다. 22만 권의 책을 오디오북, 챗북과 같은 형태로 일상 곳곳에 연결하고, 밀리 페어링으로 언제 어디서나 독서의 흐름을 이어가도록 돕습니다. 여기에 ''AI 스마트 키워드''을 취향에 꼭 맞는 책을 추천해 줍니다. 일상 속에서 책과 마주하는 무수한 찰나가 모여 비로소 나만의 색을 담은 단단한 취향이 완성됩니다. 2,500여 출판사와 910만 구독자가 함께 만들어가는 다채로운 이야기 속에서 나의 취향을 발견해 보세요.', 'https://www.millie.co.kr/v3/brand', null, 107),
  (108, 'A1703', null, '예스24', 'YES24', null, null, false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], '예스24는 1998년 대한민국 최초의 인터넷 서점으로 출발하여, 현재는 책과 티켓, 음반, 굿즈를 아우르는 국내 대표 문화콘텐츠 플랫폼으로 성장했습니다. YOUR EVERY STORY라는 슬로건 아래, 독자들이 책을 통해 영감을 얻고 자신만의 고유한 이야기를 창조할 수 있도록 새로운 동기를 제공합니다. 25년 넘게 축적된 방대한 빅데이터와 견고한 IT 기술력을 바탕으로 독자 개개인에게 최적화된 큐레이션 경험을 선사하며, 전자책 단말기 크레마와 구독 서비스 ''크레마클럽''을 통해 디지털 독서 환경의 표준을 제시합니다. 예스24는 단순히 도서를 유통하는 역할을 넘어, 젊은 작가를 응원하고 어린이 독서 문화를 확산하는 등 지속 가능한 출판 생태계를 구축하는 데 앞장서고 있습니다.', 'https://www.yes24.com', 'https://www.instagram.com/yes24_official/', 108),
