  (141, 'A1904', null, '갈라파고스', 'Galapagos', null, null, false, array['철학','사회과학','역사']::text[], '도서출판 갈라파고스는 2003년에 설립되었으며 첫 책인 다윈의 자서전 를 출간한 이래 생태환경 관련 도서와 인문사회 교양서 위주로 지금까지 100여 종의 책을 펴냈습니다. 자연과 인간의 공존, 인간과 인간의 공존을 희망하며, 시간이 흘러도 가치가 퇴색되지 않을 좋은 책들을 한 권 한 권 공들여 만들고 있습니다. 를 비롯하여 아마티아 센의 , 장 지글러의 등을 펴내며 반전 평화, 빈곤과 기아 문제, 인권, 환경 생태, 공동체적 삶과 대안적 모델을 꾸준히 이야기해왔습니다.', 'https://galapagosp.com/', 'https://www.instagram.com/galapagos.books/', 141),
  (142, 'A1905', null, '도서출판 들녘', 'Dulnyouk Publishing Co.', null, null, false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], '도서출판 들녘은 1987년 사회과학 출판사로 창립되었습니다. 1990년대에 이르러 소설을 비롯한 문예물을 발간하기 시작했고, 1994년 출간한 퇴마록으로 1천만 부 판매라는 기록을 세우면서 장르소설 분야에 큰 획을 그었습니다. 현재 인문, 사회, 문학 등 다양한 분야에서 양서를 출간하는 종합출판사로 자리매김하였습니다. 2021년 장르문학 임프린트 고블을 론칭하여 "어두운 광산 속에서 황금을 캐는 고블린처럼 빛나는 이야기를 발굴한다"라는 기조 아래, SF, 호러, 미스터리, 스릴러, 환상문학 등 다양한 장르의 문학을 펴내고 있습니다.', null, 'https://www.instagram.com/dulnyouk_pub/', 142),
  (143, 'A1906', null, '원더박스', 'WONDERBOX', null, null, false, array['사회과학','역사','아동']::text[], '생각의 숨을 고르는 책, 원더박스 무엇이든지 빨리 결정하고, 숨 돌릴 새도 없이 내가 누구인지를 밝혀야 하는 시대입니다. 하지만 그렇게 급하게, 서두르면서, 혹시 우리의 소중한 무언가를 놓치고 있는 건 아닐까요. 이게 정말 맞는 걸까, 다른 길은 없을까를 궁리하는 일상 속의 작은 틈새. 질문이 열어 준 낯섦에 몸을 내맡기는 도전의 과정. 원더박스는 그런 시간의 힘을 응원합니다. 반 템포 천천히, 깊고 자유로워지는 시간과 함께하기. 원더박스가 책을 만드는 이유입니다.', 'https://blog.naver.com/wonderbox13/', null, 143),
  (144, 'A1907', null, '(주)크레용하우스', 'Crayonhouse. co. Ltd', null, null, false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], '아동출판 크레용하우스는 1998년 문을 열었습니다. 어른이 되어서도 기억할 수 있는, 어린이들의 친구가 되고 인생의 스승이 되는 책을 한 권 한 권 정성껏 만들기 위해 노력해 왔습니다. 어린이들에게 가장 가까운 곳에 있는 크레용처럼 친숙하면서 또 재미있고 감동 있는 이야기는 물론 정보가 담긴 교양 과학 책 등 다양한 컨텐츠로 어린이, 청소년 책을 선보이고 있습니다. 빚은책들은 어른들에게도 가치와 재미를 선물할 수 있는 책을 만들기 위해 시작되었습니다. 빚은책들이 주목하고 있는 분야는 인문, 교양 과학, 환경이며 문학 쪽 파트로는 청소년과 어른이 모두 재미있게 읽을 수 있는 장르소설에 주목하고 있습니다.', 'http://www.crayonhouse.co.kr', null, 144),
  (145, 'A2001', null, '생명의말씀사', 'WORD OF LIFE PRESS', null, null, false, array['철학','종교','전자출판']::text[], '(재)팀선교회생명의말씀사는 1953년 6.25 직후 정신적, 영적으로 황폐화된 이 땅에 생명의 말씀으로 빛을 밝히고자 탄생하였습니다. 미국의 TEAM(The Evangelical Alliance Mission)선교사들에 의하여 전도지를 뿌리는 일에서부터 시작하여 70여 년 동안 5,000여 종에 달하는 양질의 신앙서적을 발행해 한국 교회에 보급하고 있으며, 총판도 운영하고 있습니다. 책나무의 사명과 함께 효율적으로 도서와 용품을 보급할 수 있는 책수레의 역할을 수행하기 위해 광화문과 강남, 구로, 일산, 의정부, 노원에 기독교전문서점을 운영하고 있습니다. 지난 70여 년 동안 흔들리지 않고 보수 복음주의 개혁신앙 노선을 지켜왔으며 주님 오시는 그날까지 바른 복음을 전하는 문서 선교의 사명을 다할 것입니다.', 'https://www.lifebook.co.kr/main/', 'https://www.instagram.com/lifebook.official/', 145),
  (146, 'A2002', null, '성서유니온', 'Scripture Union Korea', null, null, false, array['종교']::text[], '성경 읽기와 묵상을 돕는 정기 간행물 매일성경을 비롯해 단행본과 어린이 신앙 도서를 출간하며, 모든 세대가 말씀 안에서 살아가도록 돕는 기독교 출판 전문기관입니다. 1972년 설립 이후 깊이 있는 콘텐츠 기획과 편집 역량을 바탕으로 출판 사역을 이어오고 있으며, 50여 년간 축적된 정기 간행물 운영 노하우를 통해 연령과 상황에 맞는 성경 읽기 콘텐츠를 개발해 왔습니다. 현재 성인, 청소년,어린이용 매일성경과 성경 읽기, 묵상, 신앙교육 관련 단행본을 출간하고 있으며, 매일성경 앱과 SNS, 묵상 강의 등 온오프라인 콘텐츠로 독자들과 소통하고 있습니다.', 'https://sum.su.or.kr:8888/', 'https://www.instagram.com/youth_qt/', 146);
